// record type with nested structured type definitions
  type record MyNestedRecordType
  {
     record
     {
       integer nestedField1, 
       float nestedField2
     } outerField1,
     enumerated {
       nestedEnum1,
       nestedEnum2
     } outerField2,
     record of boolean outerField3,
     map from charstring to charstring outerfield4
  }
  // record type with nested subtype definitions
  type record MyRecordTypeWithSubtypedFields
  {
     integer  field1 (1 .. 100),
     charstring field2 length ( 2 .. 255 )
  }

import from Math all;
  type record Pixel {
     Math.Point,   // embedded field with implicit name Point
     charstring color,
     float z
  }
  var Pixel p := { Point := {4,8}, color := "red" };
  log(p.Point.x); // explicit access to field x
  log(p.x);    // access to promoted field x
  log(p.z);    // is NOT allowed: z is not a promoted field. Explicit access is required.
  module Math {
     type record Point { integer x, integer y, integer z }
  }

